Kind: verified_example
Provenance: authored
Verification: passed
Authored example: written for foss-mcp against the pinned library, not taken from the upstream README; published only after the ingestion verifier compiled or ran it against that commit.
Renames the default worksheet, adds two more, removes one by index, saves the workbook to a temporary file, reloads it and reads the surviving worksheet names and count back from the reloaded workbook.

Example:
// Authored example: add, rename and remove worksheets, then read the final worksheet names back after a reload.
import { Workbook } from "./aspose_cells";

async function main() {
  const workbook = new Workbook();
  workbook.worksheets.get(0)!.name = "Summary";

  const data = workbook.worksheets.addWorksheet("Data");
  data.putValue("A1", "Row count");
  data.putValue("B1", 3);

  workbook.worksheets.addWorksheet("Scratch");
  const removed = workbook.worksheets.removeWorksheet(2);

  const path = "outputfiles/cand4.xlsx";
  await workbook.save(path);

  const loaded = await Workbook.load(path);
  const names = loaded.worksheets.worksheets.map((sheet) => sheet.name);
  console.log("removed:", removed, "worksheets:", names, "count:", loaded.worksheets.length);

  if (!removed) throw new Error("expected removeWorksheet to report success");
  if (loaded.worksheets.length !== 2) throw new Error(`expected 2 worksheets, got ${loaded.worksheets.length}`);
  if (names[0] !== "Summary" || names[1] !== "Data") {
    throw new Error(`expected [Summary, Data], got ${names.join(",")}`);
  }
  console.log("cand4 OK");
}

main();
