// Authored example: apply font, fill and alignment style settings to a cell and read every setting back.
import { Workbook, Style } from "./aspose_cells";

function main() {
  const workbook = new Workbook();
  const worksheet = workbook.worksheets.get(0)!;

  const style = new Style();
  style.setBold(true);
  style.setFontName("Arial");
  style.setFontColor("FFFFFFFF");
  style.setForegroundColor("FF2278D4");
  style.setHorizontalAlignment("center");
  style.setWrapText(true);

  const header = worksheet.getCell2("A1");
  header.putValue("Header");
  header.setStyle(style);

  const applied = header.style!;
  const bold = applied.font?.bold;
  const fontName = applied.font?.name;
  const fontColor = applied.font?.color;
  const foreground = applied.fill?.fgColor;
  const horizontal = applied.alignment?.horizontal;
  const wrapText = applied.alignment?.wrapText;

  console.log("bold:", bold, "font:", fontName, "fontColor:", fontColor, "fg:", foreground, "halign:", horizontal, "wrap:", wrapText);

  if (bold !== true) throw new Error("expected bold style to be set");
  if (fontName !== "Arial") throw new Error(`expected font Arial, got ${fontName}`);
  if (fontColor !== "FFFFFFFF") throw new Error(`expected font color FFFFFFFF, got ${fontColor}`);
  if (foreground !== "FF2278D4") throw new Error(`expected foreground FF2278D4, got ${foreground}`);
  if (horizontal !== "center") throw new Error(`expected center alignment, got ${horizontal}`);
  if (wrapText !== true) throw new Error("expected wrapText to be set");
  console.log("cand3 OK");
}

main();
