Writes a string, two numbers and a formula into a worksheet, checks the formula in memory, saves the workbook to a temporary file, reloads it and reads each typed value back from the reloaded sheet.

Example:
// Authored example: write typed values and a formula into a worksheet, save and reload it, and read the saved values back.
import { Workbook } from "./aspose_cells";

async function main() {
  const workbook = new Workbook();
  const worksheet = workbook.worksheets.get(0)!;

  worksheet.putValue("A1", "Widgets");
  worksheet.putValue("B1", 42);
  worksheet.putValue("C1", 19.99);
  const total = worksheet.getCell2("D1");
  total.setFormula("B1*C1");

  console.log("formula before save:", total.formula);
  if (total.formula !== "B1*C1") throw new Error(`expected formula B1*C1, got ${total.formula}`);

  const path = "outputfiles/cand1.xlsx";
  await workbook.save(path);

  const loaded = await Workbook.load(path);
  const loadedSheet = loaded.worksheets.get(0)!;
  const name = loadedSheet.getCell2("A1").value;
  const quantity = loadedSheet.getCell2("B1").value;
  const price = loadedSheet.getCell2("C1").value;

  console.log("name:", name, "quantity:", quantity, "price:", price);

  if (name !== "Widgets") throw new Error(`expected name Widgets, got ${name}`);
  if (quantity !== 42) throw new Error(`expected quantity 42, got ${quantity}`);
  if (price !== 19.99) throw new Error(`expected price 19.99, got ${price}`);
  console.log("cand1 OK");
}

main();
