  if (parsed[0].cells.A2 !== "Alice" || parsed[0].cells.B2 !== 25) {
    throw new Error(`unexpected JSON export cells: ${json}`);
  }
  if (!markdown.includes("Alice") || !markdown.includes("|")) {
    throw new Error(`unexpected Markdown export: ${markdown}`);
  }
  console.log("cand5 OK");
}

main();
